import type { z } from "zod";
import type { ConversationPlanRequest, ConversationPlanSchema } from "./conversationPlan";
import type { ConversationChangeSchema } from "./conversationChanges";
import { matchesRole, resolveProductReference, messageProductReference } from "./productReference";
import { explicitCollection, requestedClothing, shoppingTarget, defaultCollectionCategory } from "./collectionPreference";
import { simpleMatchingSet, jacketPairingRequest, isJacket } from "./combinedShoppingRequest";
import { removedRequirements, taskReplacement, isShoppingRequest } from "./taskState";
import { explicitDressCode } from "./dressCode";

type Plan = z.infer<typeof ConversationPlanSchema>;
type Change = z.infer<typeof ConversationChangeSchema>;
const colours = "black|white|ivory|cream|blue|navy|red|pink|green|beige|brown|silver|gold|grey|gray|lavender|purple|yellow|orange|taupe";
const rolePattern = /\b(dress(?:es)?(?![ -]+(?:shirts?|shoes?|code|me|us|up|down)\b)|skirts?|jackets?|blazers?|shirts?|trousers?|pants|bags?|shoes?|necklaces?|accessories|accessory|clothing|clothes)\b/i;

// Repair only known requirement paraphrases against explicit, literal words in
// this message. Arbitrary labels and every other evidence field still fail closed.
export function groundRequirementEvidence(message: string, candidate: Plan): Plan {
  const plan = structuredClone(candidate);
  const rules = [
    { label: /^(?:no polyester|without polyester|polyester[- ]free)$/i, quote: /\b(?:(?:no|without) polyester|polyester[- ]free)\b/i },
    { label: /^(?:no (?:elastic|elasticated)(?: waist(?:band)?)?|non[- ]elastic(?:ated)? waist(?:band)?)$/i, quote: /\bno (?:elastic|elasticated)(?: waist(?:band)?)?\b/i },
    { label: /^(?:full[- ]length(?: not cropped)?|not cropped|no cropped(?: length)?)$/i, quote: /\b(?:full[- ]length(?: not cropped)?|not cropped|no cropped(?: length)?)\b/i },
    { label: /^(?:high[- ]waist(?:ed)?)$/i, quote: /\bhigh[- ]waist(?:ed)?\b/i },
  ];
  plan.changes = plan.changes.flatMap(change => {
    if (change.field !== "unresolved" || change.operation !== "add" ||
        message.toLowerCase().includes(change.evidence.toLowerCase())) return [change];
    const quotes = change.value.map(label => rules.find(rule => rule.label.test(label.trim()))?.quote.exec(message)?.[0]);
    if (quotes.some(quote => !quote)) return [change];
    const starts = quotes.map(quote => message.toLowerCase().indexOf(quote!.toLowerCase()));
    const start = Math.min(...starts);
    const end = Math.max(...starts.map((position, index) => position + quotes[index]!.length));
    return [{ ...change, evidence: message.slice(start, end) }];
  });
  return plan;
}

// Ground a few unambiguous shopping constraints in the customer's actual words.
// This is deliberately not a general language parser: unknown/compound requests
// still go through the interpreter and the existing fail-closed validation.
export function groundConversationPlan(request: ConversationPlanRequest, candidate: Plan): Plan {
  const plan = structuredClone(candidate);
  const message = request.message;
  const identity = messageProductReference(request.context, message);
  const compoundEdit = /\b(?:under|below|cheaper|similar|more like|different colou?r|no (?:beige|yellow|black|white)|instead)\b/i.test(message);
  if (identity.status === "resolved") {
    if (plan.reference) plan.reference = identity.reference;
    if (plan.action === "none" && plan.answer?.kind === "product" && !plan.answer.continuation) plan.answer.references = [identity.reference];
    if (request.pending_answer && compoundEdit && !/\b(?:why|what|made of|material|wash|fit me)\b/i.test(message)) {
      plan.action = "refine"; plan.reference = identity.reference; plan.answer = null; plan.question = null; plan.continuation = false;
    }
  }
  if (identity.conflict && (plan.reference || plan.answer?.kind === "product")) {
    plan.action = "clarify"; plan.reference = null; plan.answer = null; plan.changes = [];
    plan.question = "The product name and position are ambiguous. Which product should I use?"; plan.continuation = false;
  }
  if (taskReplacement(message) && ["new_search", "refine", "cross_sell", "clarify"].includes(plan.action) && requestedClothing(message)) {
    plan.action = "new_search"; plan.outfit_request = null; plan.reference = null; plan.answer = null; plan.question = null; plan.continuation = false;
  }
  if (isShoppingRequest(message) && requestedClothing(message) && request.pending_answer && identity.status === "absent") {
    plan.answer = null; plan.continuation = false;
  }
  const allItems = /\b(?:shared|global|all (?:items|recommendations|future searches)|every item|throughout|for everything)\b/i.test(message);
  if (!allItems) plan.changes = plan.changes.map(change =>
    change.scope === "shared" && !["gender", "category", "subcategory", "product_type", "size", "unresolved"].includes(change.field) ? { ...change, scope: "item" } : change);
  const event = message.match(/\b(?:wedding(?: guest)?|cocktail|office|work)\b/i);
  if (event && !/\b(?:not|no)\s*$/i.test(message.slice(0, event.index))) {
    const mapped = explicitDressCode(message) === "wedding_guest" ? "Wedding Guest" : /cocktail/i.test(event[0]) ? "Formal" : /wedding/i.test(event[0]) ? "Wedding Guest" : "Work";
    plan.changes = plan.changes.map(change => change.field === "occasion" && /^(?:cocktail|office)$/i.test(String(change.value)) ? { ...change, value: mapped } : change);
    // An event supplies an occasion, not an additional hard style choice.
    plan.changes = plan.changes.filter(change => !(change.field === "style" && typeof change.value === "string" &&
      /\b(?:wedding|cocktail|office|work)\b/i.test(change.evidence) && !message.toLowerCase().includes(change.value.toLowerCase())));
    if (plan.outfit_request) plan.outfit_request.items = plan.outfit_request.items.map(item => ({ ...item,
      occasion: /^(?:cocktail|office)$/i.test(item.occasion ?? "") ? mapped : item.occasion }));
    // These are supported event contexts, not construction/certification facts.
    // Remove only a duplicated bare label, retaining compound unknowns.
    plan.changes = plan.changes.flatMap(change => {
      if (change.field !== "unresolved" || change.operation !== "add") return [change];
      const value = change.value.filter(label => !/^(?:cocktail(?: dress code)?|office(?: wear)?)$/i.test(label.trim()));
      return value.length ? [{ ...change, value }] : [];
    });
  }
  for (const scope of ["item", "shared"] as const) {
    if (scope === "shared" && !allItems) continue;
    const labels = request.scopes[scope === "item" ? "unresolved_item" : "unresolved_shared"];
    const removed = removedRequirements(message, labels);
    if (removed.length) {
      plan.changes = plan.changes.filter(change => !(change.scope === scope && change.field === "unresolved" && change.operation === "remove"));
      plan.changes.push({ scope, field: "unresolved", operation: "remove", value: removed, evidence: message.slice(0, 250) });
      if (plan.action === "clarify") { plan.action = "refine"; plan.question = null; plan.continuation = false; }
    }
  }
  const matchingSet = simpleMatchingSet(message);
  if (matchingSet && ["new_search", "refine", "cross_sell", "clarify"].includes(plan.action)) {
    plan.action = request.styling?.outfit_request ? "refine" : "new_search";
    plan.outfit_request = matchingSet; plan.discovery_intent = null;
    plan.question = null; plan.continuation = false;
    plan.changes = plan.changes.filter(change => !["category", "subcategory", "product_type", "size", "min_price", "max_price"].includes(change.field));
  }
  const addition = message.match(/\b(?:show|find)(?: me)?\s+(?:(?:some|other|new|flat|black|formal)\s+)*(shoes?|flats?|bags?|necklaces?)\b/i);
  if (addition && !taskReplacement(message) && /\b(?:keep|saved|selected|to go with|to match)\b/i.test(message)) {
    const saved = request.styling?.outfit ?? [];
    const named = saved.filter(piece => message.toLowerCase().includes(piece.product_name.toLowerCase()));
    const anchors = named.length ? named : saved.filter(piece => /\b(?:keep|saved|selected)\b[^.!?]{0,50}\bdress\b/i.test(message) && piece.subcategory === "Dresses");
    if (anchors.length === 1 && /\b(?:new_search|refine|cross_sell|clarify)\b/.test(plan.action)) {
      plan.action = "cross_sell"; plan.reference = { kind: "id", value: anchors[0].product_id };
      plan.outfit_request = null; plan.answer = null; plan.question = null; plan.continuation = false;
      const category = /shoe|flat/i.test(addition[1]) ? "Shoes" : /bag/i.test(addition[1]) ? "Bags" : "Accessories";
      plan.changes = plan.changes.filter(change => !["category", "subcategory", "product_type", "size"].includes(change.field));
      plan.changes.push({ scope: "item", field: "category", operation: "set", value: category, evidence: addition[0] });
      if (/\bflat/i.test(addition[0])) plan.changes.push({ scope: "item", field: "product_type", operation: "set", value: "Flats", evidence: addition[0] });
    }
  }
  if (plan.outfit_request && jacketPairingRequest(message)) {
    const focused = request.context.focused;
    const candidates = [...request.context.latest, ...(request.context.selected ?? []), ...(request.context.previous?.flat() ?? [])].filter(isJacket);
    const ids = [...new Set(candidates.map(product => product.product_id))];
    if (!plan.reference || plan.reference.kind === "context") {
      plan.reference = focused && isJacket(focused) ? { kind: "id", value: focused.product_id }
        : ids.length === 1 ? { kind: "id", value: ids[0] } : { kind: "context" };
    }
  }
  // Discovery prompts are optional suggestions, not pending transactions.
  // A model may copy their question or mark a short reply as a continuation;
  // neither should prevent a clear search from proceeding through validation.
  if (request.discovery && !request.pending && ["new_search", "refine", "discover"].includes(plan.action)) {
    plan.continuation = false;
    plan.question = null;
  }
  const pause = message.match(/\b(?:no other items|no extras|no extra recommendations(?: after [^.]+)?|i only need (?:a |an )?(?:dress|shoes|necklace))\b/i);
  if (pause) {
    plan.styling_intent ??= { preferences: [], outfit_changes: [], owned_categories: [], offers: null };
    plan.styling_intent.offers = { paused: true, evidence: pause[0] };
  }
  if (request.styling?.external_items.length && /\b(?:work from|use (?:that|the|my))\b.{0,30}\bdescription\b/i.test(message)) {
    plan.action = "cross_sell"; plan.reference = null; plan.answer = null; plan.question = null;
    plan.changes = []; plan.continuation = false;
  }
  if (plan.action === "refine" && plan.reference?.kind === "context" && !plan.outfit_request) plan.reference = null;
  if (plan.answer?.purpose && !plan.answer.continuation) {
    const purpose = plan.answer.purpose.match(/\b(?:beach wedding|wedding guest|smart casual|date night|everyday wear|wedding|work|casual|brunch|party|formal|travel)\b/i);
    if (purpose) plan.answer.purpose = purpose[0];
    else if (/^(?:extra cost|price difference|improve |gain |go with |match )/i.test(plan.answer.purpose)) plan.answer.purpose = null;
  }
  if (plan.answer && !plan.answer.continuation && plan.answer.kind !== "policy" &&
      /\b(?:material|made (?:of|from)|fabric|composition)\b/i.test(message) && !plan.answer.topics.includes("material")) {
    plan.answer.topics.push("material");
  }
  if (plan.answer && !plan.answer.continuation && plan.answer.kind !== "policy") {
    for (const [pattern, topic] of [
      [/\b(?:wash|washable|care instructions|clean)\b/i, "care"],
      [/\b(?:waist|length|measurements?|construction)\b/i, "general"],
      [/\b(?:sizes? (?:listed|available)|is (?:XS|S|M|L|XL|[0-9]+) listed)\b/i, "sizes"],
    ] as const) if (pattern.test(message) && !plan.answer.topics.includes(topic)) plan.answer.topics.push(topic);
  }
  if (plan.action === "none" && plan.answer?.kind === "product" && !plan.answer.continuation && !/\b(?:compare|versus|difference)\b/i.test(message)) {
    const ordinal = message.match(/\b(first|second|third|fourth|fifth)\s+(dress(?:es)?|bags?|shoes?|necklaces?)\b/i);
    if (ordinal) {
      const position = { first: 1, second: 2, third: 3, fourth: 4, fifth: 5 }[ordinal[1].toLowerCase()]!;
      const resolved = resolveProductReference(request.context, { kind: "position", position, subcategory: ordinal[2] });
      const anchors = new Set(request.styling?.outfit.map(product => product.product_id));
      const onlyOwnedAnchors = plan.answer.topics.includes("recommendation") && !/\band\b/i.test(message) &&
        plan.answer.references.every(reference => {
          const product = resolveProductReference(request.context, reference);
          return product.status === "resolved" && (resolved.status === "resolved" && product.product_id === resolved.product_id || anchors.has(product.product_id));
        });
      if (resolved.status === "resolved" && (plan.answer.references.length <= 1 || onlyOwnedAnchors)) {
        plan.answer.references = [{ kind: "id", value: resolved.product_id }];
      }
    }
  }
  if (plan.answer?.kind === "product" && !plan.answer.continuation &&
      plan.answer.references.every(reference => reference.kind === "context")) {
    const roles = [...new Set([...message.matchAll(/\bthe\s+(dress|shoes?|bag|necklace)\b/gi)].map(match => match[1].toLowerCase()))];
    const matching = roles.length === 1 ? request.context.latest.filter(product => matchesRole(product, roles[0])) : [];
    if (matching.length === 1) plan.answer.references = [{ kind: "id", value: matching[0].product_id }];
  }
  const searching = ["new_search", "refine", "cheaper", "cross_sell", "upsell", "discover"].includes(plan.action);
  if (!searching) return plan;
  for (const [pattern, field] of [[/\b(?:any fit|drop (?:the )?fit restriction)\b/i, "fit"], [/\bany colou?r\b/i, "preferred_colours"]] as const) {
    const permission = message.match(pattern);
    if (!permission) continue;
    plan.changes = plan.changes.filter(change => !(change.scope === "item" && change.field === field));
    plan.changes.push(field === "fit" ? { scope: "item", field, operation: "set", value: null, evidence: permission[0] }
      : { scope: "item", field, operation: "set", value: [], evidence: permission[0] });
    if (plan.outfit_request) plan.outfit_request.items = plan.outfit_request.items.map(item => ({ ...item, [field]: field === "fit" ? null : [] }));
  }
  if (plan.action === "discover" && /\bweekends?\b/i.test(message)) {
    const evidence = message.match(/\bweekends?\b/i)![0];
    plan.changes = plan.changes.filter(change => change.field !== "occasion");
    plan.changes.push({ scope: "item", field: "occasion", operation: "set", value: "Casual", evidence });
  }
  const collection = explicitCollection(message, Boolean(request.collection?.checkpoint));
  if (request.collection?.checkpoint && collection && ["new_search", "refine", "discover"].includes(plan.action)) {
    // The saved scopes already contain the original brief. A collection answer
    // must not start a fresh item and erase that brief. A genuinely different
    // requested item can still take its ordinary new_search path below.
    const role = message.match(rolePattern);
    const differentItem = role && !/clothing|clothes/i.test(role[0]) &&
      !(/dress/i.test(role[0]) && request.scopes.item.subcategory === "Dresses");
    if (!differentItem) {
      const checkpoint = request.collection.checkpoint;
      plan.action = checkpoint.action === "discover" && !request.scopes.item.category ? "discover" : "refine";
      plan.discovery_intent = plan.action === "discover" ? plan.discovery_intent ?? checkpoint.discovery_intent ?? "browse" : null;
      plan.continuation = false; plan.question = null;
    }
  }
  const shoppingStart = message.search(/\b(?:show(?: me)?|find(?: me)?|i want|i need|let['’]s (?:try|start with)|browse)\b/i);
  const shoppingBrief = shoppingStart >= 0 ? message.slice(shoppingStart) : message;
  const occasion = shoppingBrief.match(/\bfor\s+(?:(?:a|an|the)\s+)?(beach wedding|wedding guest|formal(?:\s+(?:events?|occasions?))?|work|everyday wear)\b/i)
    ?? shoppingBrief.match(/\b(formal)\s+(?:clothes|clothing|wear)\b/i);
  if (occasion && !/\b(?:not|except)\s*$/i.test(shoppingBrief.slice(0, occasion.index))) {
    const label = /^formal/i.test(occasion[1]) ? "Formal" : /^work/i.test(occasion[1]) ? "Work"
      : /^everyday/i.test(occasion[1]) ? "Casual" : /^beach/i.test(occasion[1]) ? "Beach Wedding" : "Wedding Guest";
    const scope = /\b(?:all items|every item|all recommendations|globally)\b/i.test(message) ? "shared" : "item";
    plan.changes = plan.changes.filter(change => !(change.scope === scope && change.field === "occasion"));
    plan.changes.push({ scope, field: "occasion", operation: "set", value: label, evidence: occasion[1] });
  }
  // Component constraints are already explicit. Flattening a dress colour or
  // size onto the whole set would incorrectly filter its shoes as well.
  if (plan.outfit_request || request.styling?.outfit_request && plan.action === "refine") {
    if (plan.outfit_request && !request.pending) plan.continuation = false;
    const componentFields = new Set(["category", "subcategory", "product_type", "size", "material", "brand_line", "preferred_colours", "excluded_colours"]);
    if (plan.outfit_request) {
      const components = plan.outfit_request.items;
      // The same colour emitted in both the dress component and ordinary
      // changes would accidentally require blue shoes too. Keep the typed,
      // component-specific representation instead of broadening its scope.
      plan.changes = plan.changes.filter(change => !componentFields.has(change.field) ||
        change.field === "unresolved" || !components.some(component => {
          const value = component[change.field as keyof typeof component];
          return value !== null && (Array.isArray(value)
            ? Array.isArray(change.value) && change.operation !== "remove" && change.value.every(label => value.includes(label))
            : value === change.value);
        }));
      if (plan.action === "refine" && plan.styling_intent) {
        const products = [...request.context.latest, ...(request.context.previous?.flat() ?? [])];
        plan.styling_intent.outfit_changes = plan.styling_intent.outfit_changes.filter(change =>
          change.operation !== "keep" || /\b(?:first|second|third|fourth|fifth|[1-5])\b/i.test(change.evidence) ||
          products.some(product => change.evidence.toLowerCase().includes(product.product_name.toLowerCase())));
      }
    }
    if (!/\b(?:all items|every item|all recommendations|throughout|every search|globally)\b/i.test(message)) {
      const local = plan.changes.map(change => ({ ...change, scope: "item" as const }));
      plan.changes = [...new Map(local.map(change => [change.field, change])).values()];
    }
    return plan;
  }
  const featureNames: Record<string, NonNullable<Plan["styling_intent"]>["preferences"][number]["value"]> = {
    pockets: "pockets", lining: "lining", "adjustable strap": "adjustable_strap", "adjustable straps": "adjustable_strap",
    "zip closure": "zip_closure", "zipper closure": "zip_closure", "machine washable": "machine_washable", "machine wash care": "machine_washable",
  };
  const requirements = new Set(plan.styling_intent?.preferences.filter(change =>
    change.kind === "requirement" && change.operation === "add").map(change => change.value));
  // A typed supported requirement must not also be a blocking "unknown".
  // Retain unknown qualifiers such as "waterproof zip closure" and negations.
  plan.changes = plan.changes.flatMap(change => {
    if (change.field !== "unresolved" || change.operation !== "add") return [change];
    const value = change.value.filter(label => {
      const key = featureNames[label.toLowerCase().replace(/^an? /, "").trim()];
      return !key || !requirements.has(key);
    });
    return value.length ? [{ ...change, value }] : [];
  });

  // Exclude an owned item's description and discarded previous direction from
  // the target brief: "own a navy dress ... I want black shoes" filters shoes.
  const start = message.search(/\b(?:show(?: me)?|find(?: me)?|i want|i need|let['’]s (?:try|start with)|browse)\b/i);
  const brief = start >= 0 ? message.slice(start) : message;
  const clothing = requestedClothing(message);
  const role = shoppingTarget(message).match(rolePattern);
  const category = clothing?.category ?? (role ? /dress|skirt|cloth|jacket|blazer|shirt|trouser|pant/i.test(role[1]) ? "Clothing"
    : /bag/i.test(role[1]) ? "Bags" : /shoe/i.test(role[1]) ? "Shoes" : "Accessories" : null);
  const put = (change: Change) => {
    plan.changes = plan.changes.filter(old => old.scope !== change.scope || old.field !== change.field);
    plan.changes.push(change);
  };
  const scope = /\b(?:all items|every item|throughout|all recommendations)\b/i.test(brief) ? "shared" as const : "item" as const;

  // Same-role browsing/refinement retains unmentioned restrictions. A genuine
  // category change still starts a fresh item scope.
  if (plan.action === "new_search" && category && category === request.scopes.item.category &&
      !/\b(?:forget|start over|new search|reset)\b/i.test(message)) plan.action = "refine";
  if (plan.action === "new_search" && request.discovery && request.discovery.stage !== "complete" &&
      !request.scopes.item.category && !/\b(?:forget|start over|new search|reset)\b/i.test(message)) plan.action = "refine";
  const pairingStart = brief.search(/\b(?:to match|to go with|for my|for (?:this|that)|with my|accompany)\b/i);
  const explicitAddition = plan.action === "cross_sell" && role && (pairingStart < 0 || role.index! < pairingStart);
  if (category && (clothing || role) && (["new_search", "refine", "discover"].includes(plan.action) || explicitAddition)) {
    const evidence = clothing?.evidence ?? role![0];
    put({ scope: "item", field: "category", operation: "set", value: category, evidence });
    if (clothing?.subcategory && !/dress|skirt/i.test(clothing.evidence)) {
      put({ scope: "item", field: "subcategory", operation: "set", value: clothing.subcategory, evidence });
    }
    const wideLeg = plan.changes.find(change => change.field === "fit" && typeof change.value === "string" && /wide[ -]?leg/i.test(change.value));
    if (wideLeg && clothing?.subcategory === "Bottoms") {
      plan.changes = plan.changes.filter(change => change !== wideLeg);
      put({ scope: "item", field: "product_type", operation: "set", value: "Wide-Leg Pants", evidence: wideLeg.evidence });
    }
    if (clothing && (clothing.subcategory === "Dresses" || /^skirts?$/i.test(clothing.evidence))) {
      put({ scope: "item", field: "subcategory", operation: "set", value: clothing.subcategory, evidence });
      plan.changes = plan.changes.filter(c => !(c.field === "product_type" && typeof c.value === "string" && /^dress(?:es)?$/i.test(c.value)));
      if (/^skirts?$/i.test(clothing.evidence) && !plan.changes.some(c => c.field === "product_type" && typeof c.value === "string" && /\bskirt\b/i.test(c.value))) {
        put({ scope: "item", field: "product_type", operation: "set", value: "Skirt", evidence });
      }
    }
    if (clothing && request.collection?.current?.source === "category_default" &&
        defaultCollectionCategory(request.scopes.item) !==
          (clothing.subcategory === "Dresses" ? "Dresses" : /^skirts?$/i.test(clothing.evidence) ? "Skirts" : null)) {
      // Switching away from a defaulted item cannot retain its old Dresses or
      // Skirts identity merely because both belong to Clothing.
      if (!plan.changes.some(c => c.scope === "item" && c.field === "subcategory")) {
        put({ scope: "item", field: "subcategory", operation: "set", value: null, evidence });
      }
      if (!plan.changes.some(c => c.scope === "item" && c.field === "product_type")) {
        put({ scope: "item", field: "product_type", operation: "set", value: null, evidence });
      }
    }
    if (role && /necklace/i.test(role[1])) {
      put({ scope: "item", field: "subcategory", operation: "set", value: "Jewellery", evidence: role[0] });
      put({ scope: "item", field: "product_type", operation: "set", value: "Necklace", evidence: role[0] });
    }
  }

  // Only positive colour constructions in the requested brief are repaired.
  // A colour in a question, exclusion, comparison anchor or owned description
  // must not become a new preference.
  const prefix = new RegExp(`\\b(${colours})\\s+(?:dresses?|bags?|shoes?|necklaces?|clothing)\\b`, "i");
  const edit = new RegExp(`\\b(?:try|keep|still|prefer)\\s+(${colours})\\b|\\b(${colours})\\s+instead of\\b`, "i");
  const match = brief.match(edit) ?? (plan.action === "upsell" ? null : brief.match(prefix));
  if (match && !/\b(?:no|not|without|exclude|avoid)\s*$/i.test(brief.slice(0, match.index))) {
    const value = match[1] ?? match[2];
    const canonical = value[0].toUpperCase() + value.slice(1).toLowerCase();
    put({ scope, field: "preferred_colours", operation: "set", value: [canonical], evidence: value });
    plan.changes = plan.changes.filter(c => !(["style", "material", "fit", "season"].includes(c.field) &&
      typeof c.value === "string" && new RegExp(`^(?:${colours})$`, "i").test(c.value)));
  }
  const size = brief.match(/\bsize\s+([\w./-]+)\b/i);
  if (size && !/^(?:yet|unknown|please|or|and)$/i.test(size[1])) {
    put({ scope: "item", field: "size", operation: "set", value: size[1], evidence: size[0] });
  }
  const maximum = brief.match(/\b(?:under|below|up to|at or below|maximum(?: is(?: now)?)?|max(?:imum)?(?: of)?|budget(?: is)?)\s*(?:A?\$)\s*(\d+(?:\.\d{1,2})?)/i)
    ?? brief.match(/(?:A?\$)\s*(\d+(?:\.\d{1,2})?)\s+(?:limit|maximum)/i)
    ?? brief.match(/\b(?:under|below|up to|maximum(?: of)?|budget(?: is)?)\s+(\d+(?:\.\d{1,2})?)\s+(?:aud|australian dollars?)\b/i);
  if (maximum && !/\b(?:total|combined|whole outfit|complete outfit)\b/i.test(message)) {
    put({ scope, field: "max_price", operation: "set", value: Number(maximum[1]), evidence: maximum[0] });
  }
  return plan;
}

lib/stylist/conversationPlan.ts:
import { z } from "zod";
import { ShoppingPreferencesSchema } from "../ai/preferenceSchema";
import {
  composePreferences, createPreferenceScopes,
  emptyShoppingPreferences, PreferenceScopesSchema,
} from "./preferenceScope";
import { ProductReferenceSchema, resolveProductReference } from "./productReference";
import { AnswerIntentSchema, PendingAnswerSchema } from "./answerPlan";
import { ConversationChangeSchema } from "./conversationChanges";
import { emptyStylingState, PrioritySchema, RecommendationContextSchema, StylingIntentSchema, StylingStateSchema } from "./commerceSchema";
import { groundConversationPlan } from "./conversationGrounding";
import { OutfitRequestSchema } from "./outfitBudgetSchema";
import { HISTORY_MESSAGES, MAX_DISPLAYED_PRODUCTS } from "./conversationLimits";
import { dressCodeFromMessage, explicitDressCode } from "./dressCode";
import { advanceDiscovery, DiscoveryIntentSchema, DiscoveryStateSchema } from "./discovery";
import { CollectionStateSchema, emptyCollectionState, explicitCollection, collectionPresentation, resolveCollection } from "./collectionPreference";
import { additiveCombinedRequest, jacketPairingRequest, isJacket } from "./combinedShoppingRequest";
import { TaskStateSchema, prepareConversationTask } from "./taskState";
import { issue } from "./conversationIssues";
export { ConversationChangeSchema } from "./conversationChanges";

const text = z.string().trim().min(1).max(250);
const ContextProductSchema = z.strictObject({
  product_id: text,
  product_name: text,
  category: ShoppingPreferencesSchema.shape.category,
  subcategory: text.nullable(),
  product_type: text.nullable(),
  price_aud: z.number().nonnegative().optional(),
  recommendation_context: RecommendationContextSchema.optional(),
});

export const PendingConversationSchema = z.strictObject({
  action: z.enum(["new_search", "refine", "cross_sell", "cheaper", "upsell", "clarify", "discover"]),
  reference: ProductReferenceSchema.nullable(),
  goal: z.string().min(1).max(2000),
  question: z.string().min(1).max(4000),
  before_scopes: PreferenceScopesSchema,
  before_styling: StylingStateSchema.optional(),
  before_collection: CollectionStateSchema.optional(),
  styling_question: z.boolean().optional(),
});

export const ConversationPlanRequestSchema = z.strictObject({
  message: z.string().trim().min(1).max(2000),
  collection: CollectionStateSchema.optional(),
  discovery: DiscoveryStateSchema.nullable().optional(),
  scopes: PreferenceScopesSchema.default(createPreferenceScopes),
  context: z.strictObject({
    focused: ContextProductSchema.nullable(),
    latest: z.array(ContextProductSchema).max(MAX_DISPLAYED_PRODUCTS),
    previous: z.array(z.array(ContextProductSchema).max(MAX_DISPLAYED_PRODUCTS)).max(2).optional(),
    selected: z.array(ContextProductSchema).max(8).optional(),
    comparison: ContextProductSchema.optional(),
  }).default({ focused: null, latest: [] }),
  history: z.array(z.strictObject({
    role: z.enum(["user", "assistant"]),
    content: z.string().min(1).max(2000),
  })).max(HISTORY_MESSAGES).default([]),
  pending: PendingConversationSchema.nullable().optional(),
  pending_answer: PendingAnswerSchema.nullable().optional(),
  styling: StylingStateSchema.optional(),
  cart_product_ids: z.array(text).max(50).optional(),
  task: TaskStateSchema.optional(),
});


export const ConversationPlanSchema = z.strictObject({
  outfit_request: OutfitRequestSchema.nullable().optional(),
  action: z.enum(["new_search", "refine", "cross_sell", "cheaper", "upsell", "clarify", "none", "discover"]),
  discovery_intent: DiscoveryIntentSchema.nullable().optional(),
  intent_evidence: text,
  reference: ProductReferenceSchema.nullable(),
  changes: z.array(ConversationChangeSchema).max(24),
  question: z.string().trim().min(1).max(400).nullable(),
  // Optional for existing offline fixtures; required by the live model schema.
  continuation: z.boolean().optional(),
  answer: AnswerIntentSchema.nullable().optional(),
  styling_intent: StylingIntentSchema.nullable().optional(),
});

export type ConversationPlanRequest = z.infer<typeof ConversationPlanRequestSchema>;
const normalise = (value: string) => value.trim().replace(/\s+/g, " ").toLowerCase();

function unsupportedRequestDetails(message: string) {
  const negativeMaterial = message.match(
    /\b(?:no|without|avoid|exclude|excluding)\s+(?:any\s+)?(leather|suede|fur|wool|silk|cotton|polyester|linen|nylon|cashmere)\b/i
  ) ?? message.match(/\b(leather|suede|fur|wool|silk|cotton|polyester|linen|nylon|cashmere)[ -]free\b/i);
  return {
    material: negativeMaterial ? normalise(negativeMaterial[1]) : null,
    completeOutfit: /\b(?:build|find|create|put together|need|want|looking for|show me)\s+(?:me\s+)?(?:a\s+)?(?:complete|full|whole)\s+(?:outfit|look)\b/i.test(message),
  };
}

export function checkConversationPlan(input: unknown, output: unknown) {
  const request = prepareConversationTask(ConversationPlanRequestSchema.parse(input));
  const originalPlan = ConversationPlanSchema.parse(output);
  // Validate model quotations before any normalization can replace a change.
  for (const change of originalPlan.changes) {
    if (!normalise(request.message).includes(normalise(change.evidence))) {
      throw new PlanEvidenceError(`changes.${change.scope}.${change.field}.evidence`);
    }
  }
  const originalIntent = originalPlan.styling_intent;
  const stylingQuotes = originalIntent ? [
    ...originalIntent.preferences.map(change => change.evidence),
    ...originalIntent.outfit_changes.map(change => change.evidence),
    ...originalIntent.owned_categories.map(change => change.evidence),
    ...(originalIntent.offers ? [originalIntent.offers.evidence] : []),
    ...(originalIntent.external_items ?? []).map(change => change.description),
  ] : [];
  for (const quote of stylingQuotes) {
    if (!normalise(request.message).includes(normalise(quote))) throw new PlanEvidenceError("styling.evidence");
  }
  const plan = groundConversationPlan(request, originalPlan);
  const combined = additiveCombinedRequest(request.message);
  if (combined && (combined.components.has("Bottoms") || combined.components.has("Shirts")) &&
      ["new_search", "refine", "cross_sell", "clarify"].includes(plan.action) && !plan.outfit_request) {
    throw new PlanValidationError("Use outfit_request with every requested component and one combined total. Bottoms and a shirt as well requests both pieces, even when phrased 'or ... as well'. Do not ask bottoms only or both or put the total on each item. Keep the referenced jacket for styling via reference.");
  }
  let scopes = PreferenceScopesSchema.parse(request.scopes);
  const continuing = plan.continuation === true;
  const originalStyling = StylingStateSchema.parse(request.styling ?? emptyStylingState());
  const resumesDescription = plan.action === "cross_sell" && originalStyling.external_items.length > 0 &&
    !plan.changes.some(change => change.field === "category" && change.value !== request.scopes.item.category);
  let styling = StylingStateSchema.parse(originalStyling);
  let stylingQuestion: string | null = null;

  if (continuing && (!request.pending ||
      (request.pending.action !== "clarify" && request.pending.action !== plan.action))) {
    throw new PlanValidationError("Continuation does not match the pending request.");
  }
  let reference = plan.reference ?? (continuing ? request.pending?.reference ?? null : null);
  if (plan.action === "cross_sell" && (!reference || reference.kind === "context") &&
      /\b(?:owned|my outfit|both|all my)\b/i.test(request.message) && originalStyling.outfit.length) {
    const role = request.message.match(/\bowned\s+(dress|bag|shoes?)\b/i)?.[1];
    const category = role ? /dress/i.test(role) ? "Clothing" : /bag/i.test(role) ? "Bags" : "Shoes" : null;
    const anchors = originalStyling.outfit.filter(piece => !category || piece.category === category);
    if (anchors.length === 1 || /\b(?:both|my outfit|all my)\b/i.test(request.message)) {
      reference = anchors[0] ? { kind: "id", value: anchors[0].product_id } : reference;
    }
  }

  function requireEvidence(quote: string, field: string) {
    const quotedText = normalise(quote);
    if (!quotedText || !normalise(request.message).includes(quotedText)) {
      throw new PlanEvidenceError(field);
    }
  }

  requireEvidence(plan.intent_evidence, "intent_evidence");
  if (plan.action === "discover") {
    const intent = plan.styling_intent;
    if (!plan.discovery_intent || plan.reference || plan.answer || plan.outfit_request ||
        intent && (intent.outfit_changes.length || intent.owned_categories.length || intent.external_items?.length || intent.offers)) {
      throw new PlanValidationError("Discovery needs discovery_intent and no reference, answer or outfit operations. Explicit filters may use changes and styling feature requirements.");
    }
    if (originalStyling.outfit_request) {
      throw new PlanValidationError("Keep the active outfit and combined budget. Use refine to browse its components; do not replace it with discovery.");
    }
  } else if (plan.discovery_intent) {
    throw new PlanValidationError("Only discover may include discovery_intent.");
  }
  const dressCode = dressCodeFromMessage(request.message) ?? explicitDressCode(request.message);
  if (plan.action === "new_search") styling.dress_code = null;
  if (["new_search", "refine", "cross_sell"].includes(plan.action) && dressCode) styling.dress_code = dressCode;
  if (plan.action === "clarify") {
    if (!plan.question) throw new PlanValidationError("A clarification plan must include a question.");
    const composition = composePreferences(scopes, { allowUnverified: request.task?.preview_unverified });
    return { status: "needs_clarification", action: plan.action, reference_product_ids: [] as string[],
      proposed_scopes: scopes, styling: originalStyling, styling_question: false,
      collection: request.collection ?? emptyCollectionState(),
      preferences: composition.status === "ready" ? composition.preferences : null,
      issues: [issue(plan.question?.startsWith("I couldn't reliably interpret") || plan.question?.startsWith("Could you rephrase") ? "interpretation_failed" : "needs_detail", "request", "task", null)],
      message: plan.question ?? "Could you rephrase that change? Your saved shopping preferences are unchanged." };
  }
  if (plan.outfit_request) {
    const outfit = plan.outfit_request;
    requireEvidence(outfit.evidence, "outfit_request.evidence");
    if (!["new_search", "refine"].includes(plan.action)) {
      throw new PlanValidationError("A shared-budget outfit search uses new_search or refine.");
    }
    const previous = originalStyling.outfit_request;
    const amounts = [...outfit.evidence.matchAll(/(?:A?\$\s*(\d+(?:\.\d{1,2})?)\b|(\d+(?:\.\d{1,2})?)\s*(?:AUD|dollars?)\b)/gi)]
      .map(match => Number(match[1] ?? match[2]));
    const unlabelledBudget = outfit.evidence.match(/\b(?:budget|total|under|maximum|up to)\b[^\d]{0,70}(\d+(?:\.\d{1,2})?)\b/i);
    if (unlabelledBudget) amounts.push(Number(unlabelledBudget[1]));
    if (outfit.total_budget_aud !== previous?.total_budget_aud && !amounts.includes(outfit.total_budget_aud)) {
      throw new PlanValidationError("The combined budget must be stated in the latest outfit evidence.");
    }
    if (outfit.items.some(item => !item.category)) throw new PlanValidationError("Specify a category for every requested outfit item.");
    if (plan.changes.some(change => ["min_price", "max_price"].includes(change.field) && change.value === outfit.total_budget_aud)) {
      throw new PlanValidationError("Store the combined total only in outfit_request.total_budget_aud, never as a per-item price change.");
    }
    // Only server-resolved references can become persistent pairing anchors.
    const { anchor_product_ids: ignoredAnchors, ...requestedOutfit } = outfit;
    void ignoredAnchors;
    styling.outfit_request = { ...requestedOutfit,
      ...(plan.action === "refine" && previous?.anchor_product_ids?.length ? { anchor_product_ids: previous.anchor_product_ids } : {}) };
  } else if (["new_search", "cross_sell", "cheaper", "upsell"].includes(plan.action)) {
    styling.outfit_request = null;
  }
  if (!continuing && ["new_search", "cross_sell"].includes(plan.action) && !resumesDescription) {
    styling.priorities = []; styling.required_features = [];
  }
  if (plan.styling_intent) {
    const intent = plan.styling_intent;
    for (const item of intent.external_items ?? []) {
      requireEvidence(item.description, "styling.external.description");
      if (item.operation === "remove") {
        if (!/\b(?:remove|forget|delete)\b/i.test(request.message)) throw new PlanValidationError("Removing a described item needs explicit permission.");
        styling.external_items = styling.external_items.filter(row => normalise(row.description) !== normalise(item.description));
        continue;
      }
      if (!/\b(?:own|owned|already have|bought|my)\b/i.test(request.message)) throw new PlanValidationError("A described owned item needs an ownership statement.");
      for (const field of ["colour", "product_type", "occasion"] as const) {
        if (item[field] && !normalise(item.description).includes(normalise(item[field]))) {
          throw new PlanValidationError(`External ${field} must be stated in the quoted garment description; otherwise use null.`);
        }
      }
      if (!styling.external_items.some(row => normalise(row.description) === normalise(item.description))) {
        let id = 1;
        while (styling.external_items.some(row => row.external_id === `external-${id}`)) id++;
        const { operation, ...description } = item; void operation;
        styling.external_items.push({ ...description, external_id: `external-${id}`, source: "customer_description" });
      }
    }
    for (const preference of intent.preferences) {
      requireEvidence(preference.evidence, `styling.${preference.kind}.evidence`);
      const isPriority = preference.kind === "priority";
      if (isPriority && !PrioritySchema.safeParse(preference.value).success) throw new PlanValidationError("Use a supported benefit priority.");
      if (!isPriority && !["lining", "adjustable_strap", "pockets", "zip_closure", "machine_washable"].includes(preference.value)) throw new PlanValidationError("Only verified boolean features can be required.");
      const values = isPriority ? styling.priorities : styling.required_features;
      const updated = preference.operation === "add" ? [...new Set([...values, preference.value])] : values.filter(value => value !== preference.value);
      styling = StylingStateSchema.parse({ ...styling, [isPriority ? "priorities" : "required_features"]: updated });
    }
    if (intent.offers) {
      requireEvidence(intent.offers.evidence, "styling.offers.evidence");
      styling.offers_paused = intent.offers.paused;
    }
    for (const owned of intent.owned_categories) {
      requireEvidence(owned.evidence, "styling.owned.evidence");
      styling.owned_categories = owned.operation === "add"
        ? [...new Set([...styling.owned_categories, owned.category])]
        : styling.owned_categories.filter(category => category !== owned.category);
    }
    const context = { ...request.context, selected: originalStyling.outfit };
    const pool = [...request.context.latest, ...(request.context.previous?.flat() ?? []), ...(request.context.focused ? [request.context.focused] : []), ...(request.context.comparison ? [request.context.comparison] : []), ...originalStyling.outfit];
    for (const change of intent.outfit_changes) {
      requireEvidence(change.evidence, "styling.outfit.evidence");
      // Interest is not consent to select an outfit piece. A short answer can
      // complete a previously explicit keep request, but a bare "I like" cannot.
      if (change.operation === "keep" &&
          !/\b(?:keep|select|choose|add\b.{0,30}\boutfit)\b/i.test(change.evidence) &&
          !(request.pending?.styling_question && /\b(?:keep|select|choose)\b/i.test(request.pending.goal))) continue;
      if (change.operation === "own" && !/\b(?:own|owned|already have|bought)\b/i.test(change.evidence) &&
          !(request.pending?.styling_question && /\b(?:own|owned|already have|bought)\b/i.test(request.pending.goal))) continue;
      const resolved = resolveProductReference(context, change.reference);
      if (resolved.status !== "resolved") { stylingQuestion = `${resolved.message} Please specify the action too, for example: keep the first product.`; break; }
      const product = pool.find(row => row.product_id === resolved.product_id)!;
      const alreadyOwned = styling.outfit.some(row => row.product_id === product.product_id && row.ownership === "owned");
      styling.outfit = styling.outfit.filter(row => row.product_id !== product.product_id);
      if (change.operation === "keep" || change.operation === "own") {
        styling.outfit = styling.outfit.filter(row => !(row.category === product.category && row.subcategory === product.subcategory));
        styling.outfit.push({ ...product, ownership: change.operation === "own" || alreadyOwned ? "owned" : "selected" });
        if (styling.purchase_budget && change.operation === "keep" && request.scopes.item.category === product.category) {
          styling.purchase_budget.product_ids = [...new Set([...styling.purchase_budget.product_ids.filter(id => styling.outfit.some(piece => piece.product_id === id)), product.product_id])];
        }
        styling.rejected_ids = styling.rejected_ids.filter(id => id !== product.product_id);
      } else if (change.operation === "reject") {
        styling.rejected_ids = [...new Set([...styling.rejected_ids, product.product_id])].slice(-50);
      }
    }
    if (stylingQuestion) styling = originalStyling;
    styling = StylingStateSchema.parse(styling);
  }
  if (plan.action === "upsell") {
    // A requested replacement WITH a must-have is also an explicit reason to
    // compare that feature. Do not rely on a second duplicate model annotation.
    const priorities = { lining: "lining", pockets: "pockets", adjustable_strap: "adjustability",
      zip_closure: "closure", machine_washable: "easy_care" } as const;
    styling.priorities = [...new Set([...styling.priorities,
      ...styling.required_features.map(feature => priorities[feature])])];
  }
  if (plan.answer) {
    const answer = plan.answer;
    if (answer.kind === "outfit_review" && (plan.action !== "none" || answer.references.length || answer.continuation || plan.styling_intent)) {
      throw new PlanValidationError("An outfit review answers from the current styling.outfit and external_items without selecting, removing or searching for products. Use action=none, references=[], continuation=false and styling_intent=null.");
    }
    if (plan.action === "upsell" && answer.kind === "compare" && answer.references.length < 2 && /\b(?:replacement|upgrade|alternative)\b/i.test(request.message)) {
      throw new PlanValidationError("Finding a replacement is an upsell search, not a comparison question about two existing products. Use action=upsell with the original reference and answer=null unless the customer separately asked about two existing products. Record explicit 'with pockets/adjustable straps/zip closure' requirements as styling requirement entries as well as relevant benefit priorities.");
    }
    if (answer.continuation && !request.pending_answer) {
      throw new PlanValidationError("An answer continuation requires a pending product question.");
    }
    const question = answer.continuation ? request.pending_answer!.question : request.message;
    if (answer.continuation && (answer.kind !== request.pending_answer!.intent.kind ||
        JSON.stringify(answer.topics) !== JSON.stringify(request.pending_answer!.intent.topics) ||
        answer.purpose !== request.pending_answer!.intent.purpose)) {
      throw new PlanValidationError("An answer continuation must retain the original question kind, topics and purpose.");
    }
    if (answer.purpose && !normalise(question).includes(normalise(answer.purpose))) {
      throw new PlanValidationError("The answer purpose must be quoted from the customer's question.");
    }
    if (answer.kind === "policy" && (answer.references.length || answer.purpose)) {
      throw new PlanValidationError("Policy questions do not select products or invent an occasion.");
    }
    if (answer.kind === "product" && answer.references.length > 1) {
      throw new PlanValidationError("Use a comparison answer for multiple product references.");
    }
    if (plan.action === "none" && plan.continuation) {
      throw new PlanValidationError("An answer cannot complete a pending shopping request.");
    }
  }
  if (plan.question !== null) {
    throw new PlanValidationError("Only a clarification plan may include a question.");
  }
  if (plan.action === "none" && (plan.changes.length > 0 || plan.reference !== null)) {
    if (plan.answer) throw new PlanValidationError("A pure answer MUST have changes=[] and top-level reference=null. Put product references ONLY in answer.references and the quoted occasion ONLY in answer.purpose. Asking why an item suits an occasion does not save that occasion as a shopping preference. If the user also explicitly requests a search, choose that shopping action instead of none.");
    throw new PlanValidationError("An unrelated turn cannot change preferences or select a product.");
  }

  // An answer to a pending cross-sell must not erase the requested extra item.
  if (!continuing && (plan.action === "new_search" || (plan.action === "cross_sell" && !resumesDescription))) {
    scopes.item = emptyShoppingPreferences();
    scopes.unresolved_item = [];
  }

  const beforeCategory = scopes.item.category;
  const touched = new Set<string>();

  for (const change of plan.changes) {
    requireEvidence(change.evidence, `changes.${change.scope}.${change.field}.evidence`);
    const field = change.field;
    const featureLabels = ["pockets", "lining", "adjustable strap", "adjustable straps", "zip closure", "zipper closure", "machine washable"];
    const labelsToCheck = Array.isArray(change.value) ? change.value : [change.value];
    if (field !== "unresolved" && labelsToCheck.some(value => typeof value === "string" && featureLabels.includes(normalise(value)))) {
      throw new PlanValidationError("Construction and care features belong only in styling_intent.preferences with a supported feature/priority key. Never store pockets, lining, adjustable straps, closures or care as colours, style, material or another catalogue label. Remove the misplaced change.");
    }
    if (field === "gender") {
      const explicit = explicitCollection(request.message, Boolean(request.collection?.checkpoint));
      if (change.scope === "shared" && (!explicit || !/\b(?:all (?:items|recommendations|future searches)|every item|throughout|globally)\b/i.test(request.message))) {
        throw new PlanValidationError("A shared collection rule needs an explicit request for all recommendations. Keep collection-question answers in item scope; the server remembers the browsing choice separately.");
      }
    }
    const key = `${change.scope}.${field}`;
    if (touched.has(key)) throw new PlanValidationError("Use one change per field per turn.");
    touched.add(key);

    if (change.scope === "shared" && ["category", "subcategory", "product_type", "size"].includes(field)) {
      throw new PlanValidationError("Product identity and size cannot be shared globally.");
    }
    const listField = field === "preferred_colours" || field === "excluded_colours" || field === "unresolved";
    if (!listField) {
      if (change.operation !== "set" || Array.isArray(change.value)) {
        throw new PlanValidationError("A scalar preference requires a set operation.");
      }
      Object.assign(scopes[change.scope], { [field]: change.value });
      continue;
    }

    const clearColours = field === "preferred_colours" && change.operation === "set" && Array.isArray(change.value) && !change.value.length;
    if (!Array.isArray(change.value) || (!change.value.length && !clearColours)) {
      throw new PlanValidationError("A list change requires one or more labels.");
    }
    if (change.operation === "set" && field !== "preferred_colours") {
      throw new PlanValidationError("Exclusions and unresolved requirements require add or remove.");
    }

    const old = field === "unresolved"
      ? scopes[change.scope === "item" ? "unresolved_item" : "unresolved_shared"]
      : scopes[change.scope][field];
    if (clearColours && old.length && !/\b(?:(?:any|all) colou?rs?|no (?:preferred |particular |specific )?colou?r(?: preference)?|(?:remove|clear|drop)\b.{0,25}\bcolou?r)\b/i.test(request.message)) {
      throw new PlanValidationError("Clearing a saved colour restriction requires explicit permission, such as any colour or remove the colour preference.");
    }
    const values = change.value;
    const labels = change.operation === "set" ? values
      : change.operation === "add" ? [...old, ...values]
        : old.filter(label => !values.some(value => normalise(value) === normalise(label)));
    const unique = [...new Map(labels.map(label => [normalise(label), label])).values()];

    if (field === "unresolved") {
      scopes[change.scope === "item" ? "unresolved_item" : "unresolved_shared"] = unique;
    } else {
      scopes[change.scope][field] = unique;
    }
  }

  if (scopes.item.category !== beforeCategory) {
    for (const field of ["subcategory", "product_type", "size"] as const) {
      if (!touched.has(`item.${field}`)) scopes.item[field] = null;
    }
  }

  const searching = ["new_search", "refine", "discover", "cross_sell", "cheaper", "upsell"].includes(plan.action);
  const browseCollection = ["new_search", "refine", "discover"].includes(plan.action) && !reference && !styling.outfit_request;
  const resolution = searching ? resolveCollection({
    message: request.message, previous: request.collection, before: request.scopes.item, preferences: scopes.item,
    newItem: !continuing && (plan.action === "new_search" || plan.action === "cross_sell" && !resumesDescription),
    allowDefault: browseCollection,
  }) : null;
  const collection = resolution?.state ?? CollectionStateSchema.parse(request.collection ?? emptyCollectionState());
  const effectiveCollection = resolution?.choice ?? request.scopes.shared.gender;
  for (const change of plan.changes.filter(change => change.field === "gender")) {
    const expected = resolution?.explicit?.choice ?? resolution?.categoryDefault?.choice;
    if (!expected || change.value !== (expected === "All" ? null : expected)) {
